{"content":"import { createFileRoute, Link, notFound } from "@tanstack/react-router";
import { useState } from "react";
import { FileText, Phone } from "lucide-react";
import { toast } from "sonner";
import { AvailabilityPill, ProductCard } from "@/components/site/ProductCard";
import { ProductThumb } from "@/components/site/ProductThumb";
import { formatPrice, getProductBySlug, getProductsBySlugs } from "@/data/catalog";
import { COMPANY, DEFAULT_SALES_REP } from "@/data/company";
import { useStore } from "@/lib/store";

export const Route = createFileRoute("/products/$slug")({
  loader: ({ params }) => {
    const product = getProductBySlug(params.slug);
    if (!product) throw notFound();
    return { product };
  },
  head: ({ loaderData }) => {
    if (!loaderData) {
      return { meta: [{ title: "Product not found | Pickrel Brothers" }, { name: "robots", content: "noindex" }] };
    }
    const p = loaderData.product;
    const title = `${p.manufacturer} ${p.mfrPartNumber} — ${p.name} | Pickrel Brothers`;
    const description = `${p.shortDescription} Order from Pickrel Brothers, wholesale plumbing and HVAC distributor in Dayton, Ohio.`;
    return {
      meta: [
        { title },
        { name: "description", content: description },
        { property: "og:title", content: title },
        { property: "og:description", content: description },
        { property: "og:type", content: "product" },
      ],
      scripts: [
        {
          type: "application/ld+json",
          children: JSON.stringify({
            "@context": "https://schema.org",
            "@type": "Product",
            name: p.name,
            sku: p.pickrelSku,
            mpn: p.mfrPartNumber,
            description: p.shortDescription,
            brand: { "@type": "Brand", name: p.manufacturer },
            offers: {
              "@type": "Offer",
              priceCurrency: "USD",
              price: p.price ?? undefined,
              availability:
                p.availability === "in-stock"
                  ? "https://schema.org/InStock"
                  : "https://schema.org/PreOrder",
              seller: { "@type": "Organization", name: COMPANY.name },
            },
          }),
        },
      ],
    };
  },
  component: ProductDetail,
});

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section className="border-t border-border pt-6">
      <h2 className="font-display text-xl font-bold uppercase tracking-wide text-navy">{title}</h2>
      <div className="mt-3">{children}</div>
    </section>
  );
}

function ProductDetail() {
  const { product } = Route.useLoaderData();
  const { addToCart, addToQuote } = useStore();
  const [qty, setQty] = useState(1);

  const related = getProductsBySlugs(product.related);
  const compatible = getProductsBySlugs(product.compatible);
  const crossRef = getProductsBySlugs(product.crossReference);

  return (
    <div className="container-page py-8">
      <nav aria-label="Breadcrumb" className="text-xs text-muted-foreground">
        <Link to="/" className="hover:text-sky">
          Home
        </Link>{" "}
        /{" "}
        <Link to="/products" search={{ q: "", category: "", brand: "" }} className="hover:text-sky">
          Products
        </Link>{" "}
        /{" "}
        <Link
          to="/products"
          search={{ q: "", category: product.category, brand: "" }}
          className="hover:text-sky"
        >
          {product.category}
        </Link>{" "}
        / <span className="text-foreground">{product.mfrPartNumber}</span>
      </nav>

      <div className="mt-4 grid gap-8 lg:grid-cols-[380px_1fr]">
        <div className="rounded-md border border-border bg-card p-6 shadow-card">
          <ProductThumb product={product} className="h-64 w-full" />
          <p className="mt-3 text-center text-xs text-muted-foreground">
            Product photography is supplied by the manufacturer feed. Call for visual confirmation.
          </p>
        </div>

        <div>
          <p className="text-sm font-bold uppercase tracking-wide text-sky">{product.manufacturer}</p>
          <h1 className="mt-1 font-display text-3xl font-bold text-navy">{product.name}</h1>
          <dl className="mt-3 flex flex-wrap gap-x-8 gap-y-1 font-mono text-sm text-muted-foreground">
            <div className="flex gap-2">
              <dt>MFR Part #</dt>
              <dd className="font-semibold text-foreground">{product.mfrPartNumber}</dd>
            </div>
            <div className="flex gap-2">
              <dt>Pickrel SKU</dt>
              <dd className="font-semibold text-foreground">{product.pickrelSku}</dd>
            </div>
          </dl>
          <p className="mt-4 text-base text-muted-foreground">{product.shortDescription}</p>

          <div className="mt-6 rounded-md border border-border bg-surface p-5">
            <div className="flex flex-wrap items-end gap-6">
              <div>
                <p className="font-display text-3xl font-bold text-navy">{formatPrice(product.price)}</p>
                <p className="text-xs text-muted-foreground">per {product.uom} &middot; list price</p>
              </div>
              <AvailabilityPill value={product.availability} />
            </div>

            <div className="mt-4 flex flex-wrap items-end gap-3">
              <label className="text-sm font-semibold text-navy">
                Qty
                <input
                  type="number"
                  min={1}
                  value={qty}
                  onChange={(e) => setQty(Math.max(1, Number(e.target.value) || 1))}
                  className="mt-1 block h-11 w-24 rounded-md border border-input bg-card px-3 text-base text-foreground"
                />
              </label>
              <button
                type="button"
                onClick={() => {
                  addToCart(product.slug, qty);
                  toast.success("Added to cart", { description: `${qty} × ${product.name}` });
                }}
                className="h-11 rounded-md bg-navy px-6 font-display font-bold uppercase tracking-wide text-navy-foreground hover:bg-navy-muted"
              >
                Add to Cart
              </button>
              <button
                type="button"
                onClick={() => {
                  addToQuote(product.slug, qty);
                  toast.success("Added to quote list", { description: product.name });
                }}
                className="h-11 rounded-md border-2 border-navy px-6 font-display font-bold uppercase tracking-wide text-navy hover:bg-secondary"
              >
                Add to Quote
              </button>
            </div>
            <p className="mt-3 text-xs text-muted-foreground">
              Account customers: contract pricing and stock are confirmed at order entry.
            </p>
          </div>

          <div className="mt-4 flex flex-wrap items-center gap-4 text-sm">
            <a href={COMPANY.phoneHref} className="flex items-center gap-2 font-semibold text-sky hover:underline">
              <Phone className="h-4 w-4" aria-hidden /> Ask {DEFAULT_SALES_REP.name} — {COMPANY.phone}
            </a>
          </div>
        </div>
      </div>

      <div className="mt-12 grid gap-10 lg:grid-cols-[1fr_320px]">
        <div className="space-y-8">
          <Section title="Product Specifications">
            <table className="w-full border border-border text-sm">
              <tbody>
                {product.specs.map((s, i) => (
                  <tr key={s.label} className={i % 2 ? "bg-surface" : "bg-card"}>
                    <th scope="row" className="w-1/3 border-b border-border px-4 py-2.5 text-left font-semibold text-navy">
                      {s.label}
                    </th>
                    <td className="border-b border-border px-4 py-2.5 text-foreground">{s.value}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </Section>

          <Section title="Description">
            <p className="text-sm leading-relaxed text-muted-foreground">{product.description}</p>
          </Section>

          <Section title="Applications">
            <ul className="list-disc space-y-1 pl-5 text-sm text-muted-foreground">
              {product.applications.map((a) => (
                <li key={a}>{a}</li>
              ))}
            </ul>
          </Section>

          <Section title="Documents & Specs">
            <ul className="divide-y divide-border rounded-md border border-border">
              {product.documents.map((d) => (
                <li key={d.label} className="flex items-center justify-between gap-3 px-4 py-3 text-sm">
                  <span className="flex items-center gap-2 text-foreground">
                    <FileText className="h-4 w-4 text-sky" aria-hidden />
                    {d.label}
                  </span>
                  <span className="text-xs font-semibold uppercase text-muted-foreground">
                    {d.kind} — request copy
                  </span>
                </li>
              ))}
            </ul>
            <p className="mt-2 text-xs text-muted-foreground">
              Manufacturer literature is attached per product as it is loaded from the document library.
            </p>
          </Section>

          {related.length > 0 && (
            <Section title="Related Products">
              <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
                {related.map((p) => (
                  <ProductCard key={p.slug} product={p} />
                ))}
              </div>
            </Section>
          )}

          {compatible.length > 0 && (
            <Section title="Compatible Products">
              <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
                {compatible.map((p) => (
                  <ProductCard key={p.slug} product={p} />
                ))}
              </div>
            </Section>
          )}

          {crossRef.length > 0 && (
            <Section title="Alternative / Cross-Reference">
              <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
                {crossRef.map((p) => (
                  <ProductCard key={p.slug} product={p} />
                ))}
              </div>
            </Section>
          )}
        </div>

        <aside className="space-y-4">
          <div className="rounded-md border border-border bg-card p-5 shadow-card">
            <h2 className="font-display text-lg font-bold uppercase text-navy">Need help specifying?</h2>
            <p className="mt-2 text-sm text-muted-foreground">
              Our inside sales team sizes, cross-references and sources parts every day.
            </p>
            <p className="mt-4 text-sm font-semibold text-navy">{DEFAULT_SALES_REP.name}</p>
            <p className="text-xs text-muted-foreground">{DEFAULT_SALES_REP.title}</p>
            <div className="mt-4 flex flex-col gap-2">
              <a
                href={DEFAULT_SALES_REP.phoneHref}
                className="rounded-md bg-navy px-4 py-2 text-center text-sm font-semibold text-navy-foreground hover:bg-navy-muted"
              >
                Call {DEFAULT_SALES_REP.phone}
              </a>
              <a
                href={`mailto:${DEFAULT_SALES_REP.email}?subject=Question about ${product.mfrPartNumber}`}
                className="rounded-md border border-input px-4 py-2 text-center text-sm font-semibold text-navy hover:bg-secondary"
              >
                Email sales
              </a>
              <Link
                to="/quote"
                className="rounded-md border border-input px-4 py-2 text-center text-sm font-semibold text-navy hover:bg-secondary"
              >
                Request a quote
              </Link>
            </div>
          </div>
        </aside>
      </div>
    </div>
  );
}
